package repack

import (
	"bufio"
	"errors"
	"fmt"
	"os"
	"strings"

	"wow-hub/internal/i18n"
)

// LoadMySQLPassword reads the password out of temp\mysql_ac.conf.
//
// That file holds a password and nothing else - no user, no host, no port -
// so the other two are hardcoded in dbping. It lives under temp\, which is
// gitignored and regenerated by scripts, so a missing or truncated file is
// an ordinary state rather than a curiosity.
//
// Every failure names the file, and none of them quote its contents: this
// password ends up in logs\wow-hub.log and in screenshots a user sends with
// a bug report.
func LoadMySQLPassword(path string) (string, error) {
	_, password, err := clientSection(path)
	if err != nil {
		return "", err
	}
	if password == "" {
		return "", errors.New(i18n.Tf("mycnf.nopass", path))
	}
	return password, nil
}

// DefaultMySQLUser is the working account, the one the servers themselves
// connect with.
//
// It has to be supplied separately because temp\mysql_ac.conf holds only a
// password: `[client]` / `password = "acore"` and nothing else. A client
// therefore still needs `-u acore` on its command line, which is what
// backups\backup-table.cmd does and what mysqldump here has to do.
const DefaultMySQLUser = "acore"

// MySQLUser returns the account the repack's own tools connect as.
//
// A [client] user in the config wins; otherwise the documented default. A
// missing or unreadable file is not an error - the same reasoning as
// MySQLRootCredentials, and the same reason this returns no error at all:
// there is nothing useful for the caller to do about it, and the default is
// right in every install this app was written for.
func MySQLUser(confPath string) string {
	user, _, err := clientSection(confPath)
	if err != nil || user == "" {
		return DefaultMySQLUser
	}
	return user
}

// Default maintenance credentials for MySQL.
//
// These are the repack's own, documented in its AGENTS.md ("Пользователи
// MySQL: acore/acore - рабочий, root/test - обслуживание"). They are a
// default, not a law: MySQLRootCredentials lets a user who changed the root
// password keep the clean shutdown path working by dropping a config file.
const (
	DefaultMySQLRootUser = "root"
	DefaultMySQLRootPass = "test"
)

// MySQLRootCredentials returns the user and password for `mysqladmin
// shutdown`.
//
// The maintenance account is the only one with the SHUTDOWN privilege -
// `acore` does not have it, which is why the working account cannot be used
// here. When confPath exists and carries a [client] section, its user and
// password win; otherwise the documented defaults are used.
//
// A missing file is not an error. The whole point is that the common case
// (nobody changed anything) needs no file at all.
func MySQLRootCredentials(confPath string) (user, password string) {
	u, p, err := clientSection(confPath)
	if err != nil {
		return DefaultMySQLRootUser, DefaultMySQLRootPass
	}
	if u == "" {
		u = DefaultMySQLRootUser
	}
	if p == "" {
		p = DefaultMySQLRootPass
	}
	return u, p
}

// clientSection parses the [client] section of a MySQL option file.
//
// Only [client] counts. A password under [mysqldump] or [mysqld] is somebody
// else's credential, and picking it up would authenticate as the wrong
// thing. User and password are both optional; callers decide what a missing
// value means.
func clientSection(path string) (user, password string, err error) {
	f, err := os.Open(path)
	if err != nil {
		return "", "", fmt.Errorf("%s: %w", i18n.Tf("mycnf.read", path), err)
	}
	defer f.Close()

	section := ""
	sc := bufio.NewScanner(f)
	for sc.Scan() {
		line := strings.TrimSpace(sc.Text())
		if line == "" || strings.HasPrefix(line, "#") || strings.HasPrefix(line, ";") {
			continue
		}

		if strings.HasPrefix(line, "[") {
			section = strings.ToLower(strings.Trim(line, "[]"))
			continue
		}

		if section != "client" {
			continue
		}

		key, value, ok := strings.Cut(line, "=")
		if !ok {
			continue
		}
		switch strings.ToLower(strings.TrimSpace(key)) {
		case "user":
			if user == "" {
				user = unquote(value)
			}
		case "password":
			// First wins. A later duplicate is a second credential, not a
			// correction, and silently taking it would change which account
			// authenticates.
			if password == "" {
				password = unquote(value)
			}
		}
	}

	if err := sc.Err(); err != nil {
		return "", "", fmt.Errorf("%s: %w", i18n.Tf("mycnf.read", path), err)
	}
	if user == "" && password == "" {
		return "", "", errors.New(i18n.Tf("mycnf.noclient", path))
	}
	return user, password, nil
}

// unquote trims surrounding whitespace and a matched pair of quotes.
func unquote(v string) string {
	v = strings.TrimSpace(v)
	if len(v) >= 2 {
		if (v[0] == '"' && v[len(v)-1] == '"') || (v[0] == '\'' && v[len(v)-1] == '\'') {
			return v[1 : len(v)-1]
		}
	}
	return v
}
